import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_source = r'''
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>

torch::Tensor maxpool2d_fp16_forward(
    torch::Tensor input,
    int64_t kernel,
    int64_t stride,
    int64_t padding,
    int64_t dilation) {

    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be fp16");

    const int64_t N = input.size(0);
    const int64_t C = input.size(1);
    const int64_t H = input.size(2);
    const int64_t W = input.size(3);

    const int64_t kernel_eff = dilation * (kernel - 1) + 1;
    const int64_t outH = (H + 2 * padding - kernel_eff) / stride + 1;
    const int64_t outW = (W + 2 * padding - kernel_eff) / stride + 1;

    auto output = torch::empty({N, C, outH, outW}, input.options());

    const dim3 block(256);
    const int64_t total = N * C * outH * outW;
    const dim3 grid((total + block.x - 1) / block.x);

    AT_DISPATCH_HALF_FLOAT(input.scalar_type(), "maxpool2d_fp16_forward", ([&] {
        const __half* inp = reinterpret_cast<const __half*>(input.data_ptr());
        __half* outp = reinterpret_cast<__half*>(output.data_ptr());

        maxpool2d_fp16_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
            inp, outp,
            N, C, H, W,
            outH, outW,
            static_cast<int>(kernel),
            static_cast<int>(stride),
            static_cast<int>(padding),
            static_cast<int>(dilation)
        );
    }));

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &maxpool2d_fp16_forward, "MaxPool2d fp16 forward (CUDA)");
}
'''

cuda_source = r'''
#include <cuda_fp16.h>
#include <cuda_runtime.h>

extern "C" __global__
void maxpool2d_fp16_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    const int N,
    const int C,
    const int H,
    const int W,
    const int outH,
    const int outW,
    const int kernel,
    const int stride,
    const int padding,
    const int dilation) {

    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = N * C * outH * outW;
    if (idx >= total) return;

    // decode linear index
    int tmp = idx;
    const int w_out = tmp % outW; tmp /= outW;
    const int h_out = tmp % outH; tmp /= outH;
    const int c = tmp % C; tmp /= C;
    const int n = tmp;

    const int h_start = h_out * stride - padding;
    const int w_start = w_out * stride - padding;
    const int kh_eff = dilation * (kernel - 1) + 1;

    __half max_val = __float2half(-65504.0f); // smallest fp16 value

    for (int kh = 0; kh < kernel; ++kh) {
        const int h_in = h_start + kh * dilation;
        if (h_in < 0 || h_in >= H) continue;
        for (int kw = 0; kw < kernel; ++kw) {
            const int w_in = w_start + kw * dilation;
            if (w_in < 0 || w_in >= W) continue;
            const int input_idx = ((n * C + c) * H + h_in) * W + w_in;
            __half val = input[input_idx];
            max_val = __hgt(val, max_val) ? val : max_val;
        }
    }

    const int out_idx = ((n * C + c) * outH + h_out) * outW + w_out;
    output[out_idx] = max_val;
}
'''

# Compile the extension
maxpool2d_cpp = load_inline(
    name="maxpool2d_cuda",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int, padding: int, dilation: int):
        super().__init__()
        self.kernel = kernel_size
        self.stride = stride
        self.pad = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ensure fp16 contiguous CUDA tensor
        x = x.to(dtype=torch.float16, device='cuda')
        return maxpool2d_cpp.forward(x, self.kernel, self.stride, self.pad, self.dilation)

# Example usage (mirrors reference script)
if __name__ == "__main__":
    batch_size = 32
    channels = 64
    height = 512
    width = 512
    kernel_size = 4
    stride = 1
    padding = 1
    dilation = 1

    model = ModelNew(kernel_size, stride, padding, dilation).cuda()
    x = torch.rand(batch_size, channels, height, width, dtype=torch.float16, device='cuda')
    y = model(x)
    print(y.shape)
